class AVLObjectBuilder extends fb.ObjectBuilder {
  final String? _ID;
  final String? _DESIGNATOR;
  final String? _NAME;
  final avlAirspaceClass? _AIRSPACE_CLASS;
  final avlVolumeType? _VOLUME_TYPE;
  final String? _COUNTRY_CODE;
  final double? _FLOOR_VALUE;
  final avlVerticalDatum? _FLOOR_DATUM;
  final double? _CEILING_VALUE;
  final avlVerticalDatum? _CEILING_DATUM;
  final String? _EFFECTIVE_FROM;
  final String? _EFFECTIVE_TO;
  final String? _TIME_OF_ACTIVITY;
  final List<double>? _VERTEX_LONGITUDE_DEG;
  final List<double>? _VERTEX_LATITUDE_DEG;
  final List<int>? _RING_OFFSETS;
  final List<int>? _RING_POLYGON_INDEXES;
  final List<avlRingRole>? _RING_ROLES;
  final int? _POLYGON_COUNT;
  final bool? _ARC_DENSIFIED;
  final double? _DENSIFICATION_TOLERANCE_M;
  final AVLProvenanceObjectBuilder? _SOURCE;

  AVLObjectBuilder({
    String? ID,
    String? DESIGNATOR,
    String? NAME,
    avlAirspaceClass? AIRSPACE_CLASS,
    avlAirspaceClass? airspaceClass,
    avlVolumeType? VOLUME_TYPE,
    avlVolumeType? volumeType,
    String? COUNTRY_CODE,
    String? countryCode,
    double? FLOOR_VALUE,
    double? floorValue,
    avlVerticalDatum? FLOOR_DATUM,
    avlVerticalDatum? floorDatum,
    double? CEILING_VALUE,
    double? ceilingValue,
    avlVerticalDatum? CEILING_DATUM,
    avlVerticalDatum? ceilingDatum,
    String? EFFECTIVE_FROM,
    String? effectiveFrom,
    String? EFFECTIVE_TO,
    String? effectiveTo,
    String? TIME_OF_ACTIVITY,
    String? timeOfActivity,
    List<double>? VERTEX_LONGITUDE_DEG,
    List<double>? vertexLongitudeDeg,
    List<double>? VERTEX_LATITUDE_DEG,
    List<double>? vertexLatitudeDeg,
    List<int>? RING_OFFSETS,
    List<int>? ringOffsets,
    List<int>? RING_POLYGON_INDEXES,
    List<int>? ringPolygonIndexes,
    List<avlRingRole>? RING_ROLES,
    List<avlRingRole>? ringRoles,
    int? POLYGON_COUNT,
    int? polygonCount,
    bool? ARC_DENSIFIED,
    bool? arcDensified,
    double? DENSIFICATION_TOLERANCE_M,
    double? densificationToleranceM,
    AVLProvenanceObjectBuilder? SOURCE,
  })
      : _ID = ID,
        _DESIGNATOR = DESIGNATOR,
        _NAME = NAME,
        _AIRSPACE_CLASS = airspaceClass ?? AIRSPACE_CLASS,
        _VOLUME_TYPE = volumeType ?? VOLUME_TYPE,
        _COUNTRY_CODE = countryCode ?? COUNTRY_CODE,
        _FLOOR_VALUE = floorValue ?? FLOOR_VALUE,
        _FLOOR_DATUM = floorDatum ?? FLOOR_DATUM,
        _CEILING_VALUE = ceilingValue ?? CEILING_VALUE,
        _CEILING_DATUM = ceilingDatum ?? CEILING_DATUM,
        _EFFECTIVE_FROM = effectiveFrom ?? EFFECTIVE_FROM,
        _EFFECTIVE_TO = effectiveTo ?? EFFECTIVE_TO,
        _TIME_OF_ACTIVITY = timeOfActivity ?? TIME_OF_ACTIVITY,
        _VERTEX_LONGITUDE_DEG = vertexLongitudeDeg ?? VERTEX_LONGITUDE_DEG,
        _VERTEX_LATITUDE_DEG = vertexLatitudeDeg ?? VERTEX_LATITUDE_DEG,
        _RING_OFFSETS = ringOffsets ?? RING_OFFSETS,
        _RING_POLYGON_INDEXES = ringPolygonIndexes ?? RING_POLYGON_INDEXES,
        _RING_ROLES = ringRoles ?? RING_ROLES,
        _POLYGON_COUNT = polygonCount ?? POLYGON_COUNT,
        _ARC_DENSIFIED = arcDensified ?? ARC_DENSIFIED,
        _DENSIFICATION_TOLERANCE_M = densificationToleranceM ?? DENSIFICATION_TOLERANCE_M,
        _SOURCE = SOURCE;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? IDOffset = _ID == null ? null
        : fbBuilder.writeString(_ID!);
    final int? DESIGNATOROffset = _DESIGNATOR == null ? null
        : fbBuilder.writeString(_DESIGNATOR!);
    final int? NAMEOffset = _NAME == null ? null
        : fbBuilder.writeString(_NAME!);
    final int? COUNTRY_CODEOffset = _COUNTRY_CODE == null ? null
        : fbBuilder.writeString(_COUNTRY_CODE!);
    final int? EFFECTIVE_FROMOffset = _EFFECTIVE_FROM == null ? null
        : fbBuilder.writeString(_EFFECTIVE_FROM!);
    final int? EFFECTIVE_TOOffset = _EFFECTIVE_TO == null ? null
        : fbBuilder.writeString(_EFFECTIVE_TO!);
    final int? TIME_OF_ACTIVITYOffset = _TIME_OF_ACTIVITY == null ? null
        : fbBuilder.writeString(_TIME_OF_ACTIVITY!);
    final int? VERTEX_LONGITUDE_DEGOffset = _VERTEX_LONGITUDE_DEG == null ? null
        : fbBuilder.writeListFloat64(_VERTEX_LONGITUDE_DEG!);
    final int? VERTEX_LATITUDE_DEGOffset = _VERTEX_LATITUDE_DEG == null ? null
        : fbBuilder.writeListFloat64(_VERTEX_LATITUDE_DEG!);
    final int? RING_OFFSETSOffset = _RING_OFFSETS == null ? null
        : fbBuilder.writeListUint32(_RING_OFFSETS!);
    final int? RING_POLYGON_INDEXESOffset = _RING_POLYGON_INDEXES == null ? null
        : fbBuilder.writeListUint32(_RING_POLYGON_INDEXES!);
    final int? RING_ROLESOffset = _RING_ROLES == null ? null
        : fbBuilder.writeListInt8(_RING_ROLES!.map((f) => f.value).toList());
    final int? SOURCEOffset = _SOURCE?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(22);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addOffset(1, DESIGNATOROffset);
    fbBuilder.addOffset(2, NAMEOffset);
    fbBuilder.addInt8(3, _AIRSPACE_CLASS?.value);
    fbBuilder.addInt8(4, _VOLUME_TYPE?.value);
    fbBuilder.addOffset(5, COUNTRY_CODEOffset);
    fbBuilder.addFloat64(6, _FLOOR_VALUE);
    fbBuilder.addInt8(7, _FLOOR_DATUM?.value);
    fbBuilder.addFloat64(8, _CEILING_VALUE);
    fbBuilder.addInt8(9, _CEILING_DATUM?.value);
    fbBuilder.addOffset(10, EFFECTIVE_FROMOffset);
    fbBuilder.addOffset(11, EFFECTIVE_TOOffset);
    fbBuilder.addOffset(12, TIME_OF_ACTIVITYOffset);
    fbBuilder.addOffset(13, VERTEX_LONGITUDE_DEGOffset);
    fbBuilder.addOffset(14, VERTEX_LATITUDE_DEGOffset);
    fbBuilder.addOffset(15, RING_OFFSETSOffset);
    fbBuilder.addOffset(16, RING_POLYGON_INDEXESOffset);
    fbBuilder.addOffset(17, RING_ROLESOffset);
    fbBuilder.addUint32(18, _POLYGON_COUNT);
    fbBuilder.addBool(19, _ARC_DENSIFIED);
    fbBuilder.addFloat64(20, _DENSIFICATION_TOLERANCE_M);
    fbBuilder.addOffset(21, SOURCEOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
